const oldU=91.4955, oldPM=79.1, oldGM=7.8;
const fit=[];
function phase(f, ps,z){return -90 + Math.atan(f/z)*180/Math.PI-ps.reduce((a,p)=>a+Math.atan(f/p)*180/Math.PI,0);}
function shape(f,ps,z){return Math.sqrt(1+(f/z)**2)/ps.reduce((a,p)=>a*Math.sqrt(1+(f/p)**2),1);}
function crossPhase(ps,z){let lo=oldU, hi=1e5;if(phase(hi,ps,z)>-180)return null;for(let j=0;j<45;j++){const m=Math.sqrt(lo*hi);if(phase(m,ps,z)>-180)lo=m;else hi=m;}return Math.sqrt(lo*hi);}
for(let n=0;n<150000;n++){
 const invgm=300+Math.random()*300;
 const z=1e6/(2*Math.PI*1.2*(1600-invgm));
 const ps=Array.from({length:3+(n%2)},()=>Math.pow(10,1.7+Math.random()*2.6));
 const pm=180+phase(oldU,ps,z);
 if(Math.abs(pm-oldPM)>0.4)continue;
 const k=oldU/shape(oldU,ps,z);
 const gm=2*Math.PI*1.2e-6*k;
 if(gm<0.00035||gm>0.0009)continue;
 const pc=crossPhase(ps,z);if(!pc)continue;
 const g=-20*Math.log10(k/pc*shape(pc,ps,z));
 if(Math.abs(g-oldGM)>.4)continue;
 const preds=[];
 for(const [c,r] of [[.95,1000],[.9,1100],[1,950],[.95,1050]]){
 const nz=1e6/(2*Math.PI*c*(r-invgm)),nk=k*1.2/c;
 let lo=1,hi=1000;
 for(let j=0;j<40;j++){const m=Math.sqrt(lo*hi);if(nk/m*shape(m,ps,nz)>1)lo=m;else hi=m;}
 const u=Math.sqrt(lo*hi),p=180+phase(u,ps,nz), np=crossPhase(ps,nz),g=-20*Math.log10(nk/np*shape(np,ps,nz));
 preds.push([u,p,g]);
 }
 fit.push({ps,invgm,gm,preds});
}
